from html import escape as esc
from commerce_data import PRODUCTS

def artwork(p):
 return '<div class="product-art product-theme-'+p['theme']+'" aria-hidden="true"><div class="product-mini"><div class="product-mini-top">'+p['short']+'<span class="product-mini-menu"><i></i><i></i><i></i></span></div><div class="product-mini-body"><div><div class="product-mini-name">'+{'studio':'Ideas.<br>Made real.','stay':'Stay<br>a little.','ink':'Make<br>your mark.','orbit':'Your<br>next move.','table':'A seat<br>at the table.','launch':'Start<br>something.'}[p['theme']]+'</div><div class="product-mini-lines"><i></i><i></i><i></i></div><div class="product-mini-button"></div></div><div class="product-mini-image"></div></div><div class="product-mini-bottom"><i></i><i></i><i></i></div></div><span class="product-art-label">PRIMO / '+p['category']+'</span></div>'

def cart_dialog(prefix):
 return '<dialog class="store-dialog" id="storeCartDialog" aria-labelledby="storeCartTitle" data-base="'+prefix+'"><div class="store-dialog-head"><span>PRIMO / DIGITAL COLLECTION</span><button type="button" data-close-cart aria-label="Close cart">×</button></div><div id="storeCartBody"><h2 id="storeCartTitle">Your collection.</h2></div></dialog>'

def register_commerce(g):
 page,section,paragraph,faq,cta=(g[x] for x in ['page','section','paragraph','faq','cta'])
 cards=''
 for p in PRODUCTS:
  cards+='<article class="market-product" data-product-id="'+p['id']+'">'+artwork(p)+'<div class="market-product-info"><small>'+esc(p['category'])+' / SAMPLE</small><h3><a href="'+p['id']+'/">'+esc(p['name'])+'</a></h3><p>'+esc(p['description'])+'</p><div class="market-price-row"><strong>$'+str(p['price'])+'<small>DEMO PRICE / USD</small></strong><button class="market-add" type="button" data-add-product="'+p['id']+'" aria-label="Add '+esc(p['name'])+' to cart">+</button></div><div class="market-product-links"><a href="'+p['id']+'/">Product details ↗</a><a href="../assets/previews/'+p['id']+'/index.html" target="_blank" rel="noopener">Open sample ↗</a></div></div></article>'
 tools='''<div class="market-demo-line"><span><strong>A new way to build with PRIMO.</strong>Explore original digital starters, UI ideas and design kits.</span><span>Demo collection · Sample USD prices · No live payments</span></div><div data-market-root><div class="market-tools"><label>Find a digital product<input id="marketSearch" type="search" placeholder="Search templates, apps and kits…" autocomplete="off"></label><label>Sort by<select id="marketSort"><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name</option></select></label><button type="button" class="market-cart-button" data-open-cart>Your collection <span data-cart-count>0</span></button></div><div class="market-categories" aria-label="Product categories">'''+''.join('<button type="button" data-category="'+value+'" aria-pressed="'+('true' if value=='all' else 'false')+'">'+label+'</button>' for value,label in [('all','All products'),('Website templates','Website templates'),('App designs','App designs'),('Design kits','Design kits')])+'''</div><p class="market-status" id="marketStatus" role="status" aria-live="polite"></p><p class="market-storage-warning" data-storage-warning hidden>Browser storage is unavailable. Your collection will be temporary.</p><div class="page-grid" id="marketGrid">'''+cards+'''</div><div class="market-empty" id="marketEmpty" hidden>No products match your search. Try another category or search term.</div></div>'''
 body=section('Digital ideas. Ready to explore.',tools)+section('From a starter to your own brand','<div class="page-grid">'+''.join('<article class="page-card"><div class="page-card-number">0'+str(i+1)+'</div><h3>'+t+'</h3>'+paragraph(d)+'</article>' for i,(t,d) in enumerate([('Discover','Browse original website and UI starters, compare the structure and open an interactive sample.'),('Try the journey','Add products to your collection and preview a checkout. This demonstration never requests payment details.'),('Make it yours','Download an evaluation starter or speak to PRIMO about customising the design for your brand.')]))+'</div>',True)+section('Before you choose',faq([('Can I purchase these products now?','Not yet. This is a marketplace demonstration with sample pricing. No payment is collected and a demo order does not grant a commercial licence.'),('What do the sample downloads include?','Each sample contains an original HTML/CSS starter, a design-tokens JSON file and a README. The dashboard sample is a front-end UI prototype, not a live application.'),('Can PRIMO customise a template for my brand?','The marketplace can become a starting point for a custom website or digital project. Use the Contact page to discuss the scope, content and integrations you need.')]))+cta('../','Start with a template. Make it your own.')
 page('marketplace/','Website Templates & UI Starters | PRIMO Marketplace','Explore PRIMO’s sample marketplace for website templates, dashboard UI starters and brand design kits. Preview designs and try a demo digital-product journey.','Creative assets. New possibilities.','A digital collection for brands, creators and teams who want a considered starting point. Explore the first PRIMO marketplace concept.',body,image='photo-1499951360447-b19be8fe80f5.jpg',kicker='PRIMO MARKETPLACE / DIGITAL PRODUCTS',extra={'commerce':True,'visual':artwork(PRODUCTS[0])},label='Marketplace')
 for p in PRODUCTS:
  prefix='../../';path='marketplace/'+p['id']+'/'
  actions='<div class="product-detail-actions"><button type="button" class="page-cta" data-add-product="'+p['id']+'">Add to collection · $'+str(p['price'])+'</button><button type="button" class="page-secondary" data-open-cart>View cart <span data-cart-count>0</span></button><a class="page-secondary" href="../../assets/downloads/'+p['id']+'-sample.zip" download>Download evaluation sample ↓</a></div><p class="product-price-note">Sample USD pricing · Demo orders only · No payment is collected.</p><p class="market-status" id="marketStatus" role="status" aria-live="polite"></p><p class="market-storage-warning" data-storage-warning hidden>Browser storage is unavailable. Your collection will be temporary.</p>'
  body=section('A starting point for '+p['audience'].lower(),actions+'<div class="page-columns"><div class="page-prose">'+paragraph(p['detail'])+'</div><ul class="page-checklist">'+''.join('<li>'+esc(x)+'</li>' for x in p['features'])+'</ul></div>')+section('Explore the actual sample','<p class="portal-muted">This is an original editable HTML/CSS evaluation starter. Sample content and designed placeholders are used in place of final brand assets.</p><iframe class="product-iframe" src="../../assets/previews/'+p['id']+'/index.html" title="'+esc(p['name'],quote=True)+' interactive evaluation sample" loading="lazy" sandbox="allow-scripts"></iframe><p><a class="page-secondary" href="../../assets/previews/'+p['id']+'/index.html" target="_blank" rel="noopener">Open full preview ↗</a></p>')+section('What you receive','<div class="page-prose">'+paragraph(p['included'])+paragraph('The files are provided for internal evaluation. A live commercial product would need final quality assurance, a commercial licence, support terms and any required production integrations. No Figma file, authentication system, database or third-party photography is included.')+'</div>',True)+section('Frequently asked questions',faq([('Is this a finished commercial template?','This is a working evaluation starter in the marketplace concept. It is not a completed commercial product and the demo checkout does not issue a paid licence.'),('Can I edit the sample?','Yes. Open the HTML and edit the copy, CSS variables and structure for evaluation. The README explains the sample’s scope and what should be reviewed before production.'),('Does the price include customisation?','The displayed amount is illustrative product pricing. A real customisation project would have a separate agreed scope and quotation.')]))+cta(prefix,'Make this direction work for your brand.')
  page(path,p['name']+' | PRIMO Marketplace',p['description'],p['name'],p['detail'],body,image='photo-1499951360447-b19be8fe80f5.jpg',kicker='MARKETPLACE / '+p['category'].upper(),extra={'commerce':True,'product':p,'visual':artwork(p)},label=p['name'])
 login='''<div class="portal-login-shell"><div class="portal-login-copy"><span class="portal-demo-pill">PRIMO / CONNECTED WORKSPACE</span><h3>Good work starts with a connection.</h3><p>Your projects, conversations and creative possibilities. Together in one space.</p><ul><li>Follow projects and review creative work.</li><li>Connect with your PRIMO team.</li><li>Access handover files and marketplace samples.</li></ul><p>Interactive preview with fictional data. Live accounts, Google authentication and password recovery are not connected yet.</p></div><form class="portal-login-form" data-portal-login data-base="../../"><span class="portal-demo-pill">ACCOUNT EXPERIENCE / DEMO</span><div class="portal-auth-tabs" aria-label="Account action"><button type="button" data-auth-mode="signin" aria-pressed="true">Sign in</button><button type="button" data-auth-mode="signup" aria-pressed="false">Create account</button></div><h3 id="portalAuthHeading">Welcome back.</h3><fieldset class="portal-role-picker"><legend>Workspace</legend><label class="portal-role-option"><input type="radio" name="role" value="client" checked>Client<small>Projects, approvals and files</small></label><label class="portal-role-option"><input type="radio" name="role" value="staff">Staff<small>Team workspace</small></label></fieldset><label class="portal-auth-field" data-signup-field hidden>Full name<input name="displayName" maxlength="100" autocomplete="off" placeholder="Sample client"></label><label class="portal-auth-field">Demo email<input id="demoLoginEmail" name="email" type="email" value="client@example.test" required autocomplete="off" aria-describedby="portalLoginNote"></label><label class="portal-auth-field">Demo password<span class="portal-password-wrap"><input id="portalPassword" name="password" type="password" required autocomplete="off" placeholder="Use the sample password below"><button type="button" data-password-toggle aria-controls="portalPassword" aria-pressed="false">Show</button></span></label><div class="portal-auth-hint">Sample password: <strong>PrimoDemo123!</strong><br>Use sample credentials only. No passwords are saved or sent.</div><p id="portalAuthStatus" class="portal-auth-status" role="status"></p><button class="portal-primary" id="portalAuthSubmit" type="submit">Sign in to demo ↗</button><button class="page-secondary" data-google-demo type="button">Preview Google sign-in ↗</button><button class="portal-auth-text" data-reset-password type="button">Forgot password?</button><p class="page-contact-note" id="portalLoginNote">Demonstration only. Client registration previews do not create an account. Staff access will require an invitation in the live service.</p></form></div>'''
 page('portal/login/','Client & Staff Portal Demo | PRIMO Workspace','Preview the PRIMO workspace with separate client and staff views for projects, approvals, tasks, messages and digital downloads.','Your work. Connected.','A considered space for clients and the PRIMO team to keep projects moving.',section('Explore the client and staff experience',login),kicker='PRIMO WORKSPACE',extra={'portal':True,'private':True,'compact':True},label='Portal login')
 invoice='''<dialog class="store-dialog portal-invoice" id="portalInvoiceDialog" aria-labelledby="portalInvoiceTitle"><div class="store-dialog-head"><span>SAMPLE INVOICE</span><button type="button" data-close-invoice aria-label="Close sample invoice">×</button></div><span class="portal-demo-pill">DEMO / NO PAYMENT DUE</span><h2 id="portalInvoiceTitle">Invoice preview.</h2><h3>DEMO-INV-001</h3><p>Sample Studio<br>Website design milestone<br>Fictional project billing example</p><div class="portal-invoice-total"><span>Illustrative amount</span><strong>USD 1,250</strong></div><p>This is a UI demonstration. It is not a tax invoice, payment request or record of a transaction.</p></dialog>'''
 for role in ['client','staff']:
  content='<section class="portal-workspace-section"><div class="wrap"><noscript><p>This demonstration workspace needs JavaScript. The public service and marketplace pages remain available without it.</p></noscript><div id="primoWorkspace" data-role="'+role+'" data-base="../../"><div class="portal-gate"><h2>Preparing the demo workspace.</h2><p>Your projects, approvals and tasks will appear here.</p></div></div></div></section>'+invoice
  page('portal/'+role+'/',role.title()+' Workspace Demo | PRIMO Group','Explore the '+role+' view of the PRIMO workspace demonstration. No live client data, authentication or payment handling is connected.',role.title()+' workspace.','A working interface demonstration. Use fictional sample data to explore the journey before production setup.',content,kicker='PRIMO WORKSPACE / '+role.upper(),extra={'portal':True,'private':True,'compact':True},label=role.title()+' workspace')
 return cart_dialog
